// Cloudflare Workers entry point.
// - Web requests go to the Next.js app built by OpenNext.
// - The daily cron trigger (wrangler.jsonc) calls the protected retry endpoint, like Vercel Cron did.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

type Env = { CRON_SECRET?: string; AUTH_URL?: string };

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) { console.warn('CRON_SECRET is not set: skipping WhatsApp retries.'); return; }
    const url = new URL('/api/cron/notifications', env.AUTH_URL || 'https://eventdesk.invalid');
    const req = new Request(url, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(handler.fetch(req, env, ctx).then(async (r: Response) => console.log('WhatsApp retry:', r.status, await r.text())));
  },
};
